"use server";

/**
 * Signs a user in and sets the session cookie.
 *
 * Owner D. Runs before any tenant is known, so it cannot go through
 * `withAction()` — there is no `Actor` to resolve yet. The rate limit is
 * charged against the anonymous bucket to blunt credential stuffing.
 *
 * Must call (do not reimplement): loginSchema, setSessionCookie,
 * consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { RateLimitedError } from "@/actions/_lib/action-errors";
import { toActionResult } from "@/lib/errors";
import { consumeRateLimit } from "@/lib/rate-limit";
import { setSessionCookie } from "@/lib/session";
import { loginSchema } from "@/schemas/auth";
import { login } from "@/server/services/auth-service";
import { resolveSession } from "@/server/services/session-service";
import { UnauthorizedActionError } from "@/actions/_lib/action-errors";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

const LOGIN_BUCKET = "auth:login";

export async function loginAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
  const parsed = loginSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, LOGIN_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(LOGIN_BUCKET, verdict.resetAt);
    }

    const { token } = await login(parsed.data);
    const principal = await resolveSession(token);
    if (principal === null) {
      throw new UnauthorizedActionError("That sign-in could not be completed.");
    }

    await setSessionCookie(token, principal.expiresAt);
    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
"use server";

/**
 * Destroys the session and clears the cookie.
 *
 * Owner D. Idempotent: signing out twice, or without a session at all, is a
 * success — the postcondition ("no session cookie") holds either way.
 *
 * Must call (do not reimplement): clearSessionCookie
 */

import { toActionResult } from "@/lib/errors";
import { clearSessionCookie, getSessionToken } from "@/lib/session";
import { destroySession } from "@/server/services/session-service";
import type { ActionResult } from "@/types/api";

export async function logoutAction(): Promise<ActionResult<null>> {
  try {
    const token = await getSessionToken();
    if (token !== null) {
      await destroySession(token);
    }
    await clearSessionCookie();
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
"use server";

/**
 * Creates a user, their first organization and the owner membership.
 *
 * Owner D. `AuthService.register` performs all three writes in one transaction;
 * this action only turns the result into a session.
 *
 * Must call (do not reimplement): registerSchema, setSessionCookie
 */

import { toActionResult } from "@/lib/errors";
import { setSessionCookie } from "@/lib/session";
import { registerSchema } from "@/schemas/auth";
import { register } from "@/server/services/auth-service";
import { createSessionToken } from "@/server/services/session-service";
import type { ActionResult } from "@/types/api";
import type { SessionPrincipal } from "@/types/member";

export async function registerAction(raw: unknown): Promise<ActionResult<SessionPrincipal>> {
  const parsed = registerSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const { user, org } = await register(parsed.data);
    const { token, expiresAt } = await createSessionToken(user.id);
    await setSessionCookie(token, expiresAt);

    const principal: SessionPrincipal = {
      userId: user.id,
      email: user.email,
      activeOrgId: org.id,
      expiresAt,
    };
    return { ok: true, data: principal, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
"use server";

/**
 * Requests and confirms a password reset.
 *
 * Owner D. The request half deliberately reports success even for an unknown
 * address so the form cannot be used to enumerate accounts; the rate limit is
 * what stops it being abused as a mail cannon.
 *
 * Must call (do not reimplement): passwordResetRequestSchema,
 * passwordResetConfirmSchema, consumeRateLimit
 */

import { RateLimitedError } from "@/actions/_lib/action-errors";
import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { toActionResult } from "@/lib/errors";
import { consumeRateLimit } from "@/lib/rate-limit";
import {
  passwordResetConfirmSchema,
  passwordResetRequestSchema,
} from "@/schemas/auth";
import {
  confirmPasswordReset,
  requestPasswordReset,
} from "@/server/services/auth-service";
import type { ActionResult } from "@/types/api";

const RESET_BUCKET = "auth:password-reset";

export async function requestPasswordResetAction(
  raw: unknown,
): Promise<ActionResult<null>> {
  const parsed = passwordResetRequestSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, RESET_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(RESET_BUCKET, verdict.resetAt);
    }

    await requestPasswordReset(parsed.data);
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}

export async function confirmPasswordResetAction(
  raw: unknown,
): Promise<ActionResult<null>> {
  const parsed = passwordResetConfirmSchema.safeParse(raw);
  if (!parsed.success) {
    return toActionResult(parsed.error);
  }

  try {
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, RESET_BUCKET);
    if (!verdict.allowed) {
      throw new RateLimitedError(RESET_BUCKET, verdict.resetAt);
    }

    await confirmPasswordReset(parsed.data);
    return { ok: true, data: null, submittedAt: new Date().toISOString() };
  } catch (error) {
    return toActionResult(error);
  }
}
